"""Build the standalone Bash entry point; no extra downloads at runtime."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HEADER = '''#!/usr/bin/env bash
# VPS Inspector - MIT license. Generated by build.py from inspector.py.
set -euo pipefail
if ! command -v python3 >/dev/null 2>&1; then
  printf '%s\\n' 'Python 3.8+ required. Debian/Ubuntu: apt-get update && apt-get install -y python3' >&2
  exit 1
fi
if ! python3 -c 'import sys; sys.exit(sys.version_info < (3, 8))'; then
  printf '%s\\n' 'Python 3.8+ required.' >&2
  exit 1
fi
exec python3 - "$@" <<'VPS_INSPECTOR_PYTHON'
'''

def build():
    source = (ROOT / "inspector.py").read_text(encoding="utf-8")
    (ROOT / "check.sh").write_bytes((HEADER + source + "\nVPS_INSPECTOR_PYTHON\n").encode("utf-8"))

if __name__ == "__main__":
    build()
